def create(
    designer_name: DesignerName,
    position: Vector,
    *,
    keys: Mapping[str, object] | None = None,
    subclass: str | None = None,
    team: int = 0,
    facing: Angles | None = None,
    key_values: list[KeyValue] | None = None,
    fields: list[FieldWrite] | None = None,
) -> Any:
    """create creates an entity of designer_name at position and addresses it
    as the class that implements it, or returns None when the host refuses.
    keys are its spawn key values, typed by the designer's Keys type, which a
    mod names where it keeps them; key_values are further key values, as
    create_entity takes them, and fields are schema fields written before the
    entity spawns. It returns Any, so a mod names the class where it keeps the
    entity."""
    class_name, key_map, default_subclass = _DESIGNERS[designer_name]
    encoded = list(key_values or [])
    for key, value in (keys or {}).items():
        map_name: str | None = key_map
        while map_name is not None:
            base, cases = _KEY_MAPS[map_name]
            case = cases.get(key)
            if case is not None:
                encoded.append(KeyValue(key=key, value=_entity_value(case, value)))
                break
            map_name = base
    handle = create_entity(
        EntityOptions(
            designer_name=designer_name,
            subclass=subclass or default_subclass,
            team=team,
            position=position,
            facing=facing,
            key_values=encoded,
            fields=list(fields or []),
        )
    )
    return None if handle is None else _CLASSES[class_name](handle)
